#!/usr/bin/env python3
"""Generate or check the Am9512 opcode constants from references/commands.csv."""
from __future__ import annotations

import argparse
import csv
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CSV_PATH = ROOT / "references" / "commands.csv"
OUT_PATH = ROOT / "src" / "amd_am9512_commands.svh"

HEADER = """// Generated by scripts/generate_commands.py from references/commands.csv.
// Do not edit by hand. The Am9512 has sixteen documented 7-bit opcodes.
"""


def read_commands() -> list[dict[str, str]]:
    with CSV_PATH.open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    if not rows:
        raise SystemExit("commands.csv is empty")
    seen = set()
    for row in rows:
        opcode = int(row["opcode"], 16)
        if opcode < 0 or opcode > 0x7F:
            raise SystemExit(f"opcode out of range: {row['opcode']}")
        if opcode in seen:
            raise SystemExit(f"duplicate opcode: {row['opcode']}")
        seen.add(opcode)
        if not row["mnemonic"].isidentifier():
            raise SystemExit(f"invalid mnemonic: {row['mnemonic']}")
    return rows


def render(rows: list[dict[str, str]]) -> str:
    lines = [HEADER]
    for row in rows:
        mnemonic = row["mnemonic"].upper()
        opcode = int(row["opcode"], 16)
        lines.append(f"localparam logic [6:0] AMD_AM9512_OP_{mnemonic} = 7'h{opcode:02x};")
    lines.append("")
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    generated = render(read_commands())
    if args.check:
        if not OUT_PATH.exists():
            print(f"missing {OUT_PATH}", file=sys.stderr)
            return 1
        current = OUT_PATH.read_text(encoding="utf-8")
        if current != generated:
            print(f"{OUT_PATH} is out of date; run scripts/generate_commands.py", file=sys.stderr)
            return 1
        print(f"commands: {OUT_PATH} is current")
        return 0
    OUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    OUT_PATH.write_text(generated, encoding="utf-8")
    print(f"wrote {OUT_PATH}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())